const videoFilters=document.querySelector('.video-filters'),videoGrid=document.querySelector('.video-grid');
function renderVideos(index){const [name,description,icon,videos]=videoGroups[index];videoFilters.innerHTML=videoGroups.map((group,i)=>`<button class="video-filter ${i===index?'selected':''}" type="button" data-video-filter="${i}" aria-pressed="${i===index}"><span class="video-filter-top"><span class="video-icon">${group[2]}</span><small>▷ ${group[3].length} video</small></span><strong>${group[0]}</strong><small>Format konten</small></button>`).join('');document.querySelector('#video-category').textContent=name;document.querySelector('#video-count').textContent=description+' · '+videos.length+' video';videoGrid.innerHTML=videos.map(([creator,id,url],i)=>`<article class="video-card"><div class="video-frame"><video controls playsinline preload="none" poster="assets/creator-videos/${id}.jpg" aria-label="Video ${creator} ${name}"><source src="assets/creator-videos/${id}.mp4" type="video/mp4">Browser kamu tidak mendukung pemutaran video.</video></div><div class="video-card-copy"><div><small>${name}</small><strong>${creator}</strong></div><a href="${url}" target="_blank" rel="noopener noreferrer" aria-label="Buka video ${creator} di TikTok">TikTok ↗</a></div></article>`).join('')}
videoFilters.addEventListener('click',e=>{const b=e.target.closest('[data-video-filter]');if(b)renderVideos(Number(b.dataset.videoFilter))});renderVideos(0);
